const DynamicButton = (record: any) => {
  const navigate = useNavigate();

  return (
    <>
      {record.index < 4 ? (
        <Button
          onClick={() => {
            navigate('details', { state: record });
          }}
          style={{ border: 'none', boxShadow: 'none' }}
        >
          <RightOutlined></RightOutlined>
        </Button>
      ) : (
        <></>
      )}
    </>
  );
};

const DynamicButton2 = (record: any) => {
  const navigate = useNavigate();

  return (
    <>
      {record.index <= 0 ? (
        <Button
          onClick={() => {
            navigate('details', { state: record });
          }}
          style={{ border: 'none', boxShadow: 'none' }}
        >
          <RightOutlined></RightOutlined>
        </Button>
      ) : (
        <></>
      )}
    </>
  );
};

